import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Day Melbourne Roundtable Q&A","description":"","frontmatter":{"title":"Ceph Day Melbourne Roundtable Q&A","date":"2015-11-13T00:00:00.000Z","updated":"2015-11-13T00:00:00.000Z","tags":["Ceph","Distributed Storage","Erasure Coding","Geo Replication","Multi","tenancy","Ceph Monitoring","Automation Deployment"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/Ceph_Day_Melbourne_Roundtable_Q_A.md","filePath":"posts/2015/Ceph_Day_Melbourne_Roundtable_Q_A.md","lastUpdated":1780459816000}'),n={name:"posts/2015/Ceph_Day_Melbourne_Roundtable_Q_A.md"};function p(a,l,r,s,u,_){return i(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 存储系统讨论会</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Ceph 开发者、用户、技术专家等</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>损坏编码（Erasure Coding）</strong>：</p><ul><li>讨论了损坏编码中奇偶校验块的数量，以及如何确定最佳配置。</li><li>分析了不同存储介质（如闪存）上的性能差异。</li><li>探讨了地理复制和异步复制在实现高可用性和性能方面的作用。</li></ul></li><li><p><strong>地理复制（Geo Replication）</strong>：</p><ul><li>讨论了在公共互联网上进行地理复制的情况。</li><li>提到了正在尝试地理复制的组织，如马来西亚政府。</li><li>讨论了实现最终一致性和选择合适工作负载的方法。</li></ul></li><li><p><strong>多租户（Multi-tenancy）和命名空间</strong>：</p><ul><li>讨论了多租户和命名空间在 Ceph 中的实现，以及如何隔离数据。</li><li>强调了安全性和性能方面的挑战。</li></ul></li><li><p><strong>Ceph 存储集群配置</strong>：</p><ul><li>讨论了如何配置 Ceph 存储集群以处理不同类型的工作负载（对象存储、块设备存储和文件系统存储）。</li><li>强调了 Ceph 架构的优势，如并行化工作负载和灵活的配置选项。</li></ul></li><li><p><strong>Ceph 的监控和管理</strong>：</p><ul><li>讨论了 Ceph 的监控和管理工具，如 Calamari、Roma 和 USM。</li><li>强调了社区开发工具的重要性以及选择合适工具的方法。</li></ul></li><li><p><strong>自动化部署</strong>：</p><ul><li>讨论了 Ceph 的自动化部署工具，如 Ceph Deploy 和其他编排工具（如 Puppet、Ansible 等）。</li><li>讨论了不同工具的优缺点以及如何选择合适的工具。</li></ul></li></ol><p><strong>后续行动计划</strong>：</p><ul><li>继续开发和完善 Ceph 的监控和管理工具。</li><li>探索地理复制和最终一致性的实现。</li><li>支持更多用户和应用程序的多租户需求。</li><li>优化 Ceph 存储集群的配置和性能。</li></ul><p><strong>关键词</strong>：</p><ul><li>损坏编码（Erasure Coding）</li><li>地理复制（Geo Replication）</li><li>多租户（Multi-tenancy）</li><li>命名空间（Namespaces）</li><li>监控和管理（Monitoring and Management）</li><li>自动化部署（Automation Deployment）</li><li>Ceph Deploy</li><li>Puppet</li><li>Ansible</li></ul>',10)])])}const h=e(n,[["render",p]]);export{d as __pageData,h as default};
